import{_ as l,a0 as t,w as n,s as h,ao as c,I as d,x as i,a1 as a,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"Linux 系统中 sudo 命令的 10 个技巧 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 系统中 sudo 命令的 10 个技巧 | LCTT (201804) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 系统中 sudo 命令的 10 个技巧 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 系统中 sudo 命令的 10 个技巧 | LCTT (201804) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201804/20180302 10 Quick Tips About sudo command for Linux systems","title":"Linux 系统中 sudo 命令的 10 个技巧","tag":"201804","desc":""},"relativePath":"201804/20180302 10 Quick Tips About sudo command for Linux systems.md","filePath":"[post].md"}'),p={name:"201804/20180302 10 Quick Tips About sudo command for Linux systems.md"};function r(u,s,g,k,b,m){const e=t("Link");return n(),h("div",null,[s[13]||(s[13]=c(`<h1 id="linux-系统中-sudo-命令的-10-个技巧" tabindex="-1">Linux 系统中 sudo 命令的 10 个技巧 <a class="header-anchor" href="#linux-系统中-sudo-命令的-10-个技巧" aria-label="Permalink to “Linux 系统中 sudo 命令的 10 个技巧”">​</a></h1><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/03/Linux-sudo-command-tips.jpg" alt="Linux-sudo-command-tips"></p><h3 id="概览" tabindex="-1">概览 <a class="header-anchor" href="#概览" aria-label="Permalink to “概览”">​</a></h3><p><code>sudo</code> 表示 “<strong>s</strong>uper<strong>u</strong>ser <strong>do</strong>”。 它允许已验证的用户以其他用户的身份来运行命令。其他用户可以是普通用户或者超级用户。然而，大部分时候我们用它来以提升的权限来运行命令。</p><p><code>sudo</code> 命令与安全策略配合使用，默认安全策略是 <code>sudoers</code>，可以通过文件 <code>/etc/sudoers</code> 来配置。其安全策略具有高度可拓展性。人们可以开发和分发他们自己的安全策略作为插件。</p><h3 id="与-su-的区别" tabindex="-1">与 su 的区别 <a class="header-anchor" href="#与-su-的区别" aria-label="Permalink to “与 su 的区别”">​</a></h3><p>在 GNU/Linux 中，有两种方式可以用提升的权限来运行命令：</p><ul><li>使用 <code>su</code> 命令</li><li>使用 <code>sudo</code> 命令</li></ul><p><code>su</code> 表示 “<strong>s</strong>witch <strong>u</strong>ser”。使用 <code>su</code>，我们可以切换到 root 用户并且执行命令。但是这种方式存在一些缺点：</p><ul><li>我们需要与他人共享 root 的密码。</li><li>因为 root 用户为超级用户，我们不能授予受控的访问权限。</li><li>我们无法审查用户在做什么。</li></ul><p><code>sudo</code> 以独特的方式解决了这些问题。</p><ol><li>首先，我们不需要妥协来分享 root 用户的密码。普通用户使用他们自己的密码就可以用提升的权限来执行命令。</li><li>我们可以控制 <code>sudo</code> 用户的访问，这意味着我们可以限制用户只执行某些命令。</li><li>除此之外，<code>sudo</code> 用户的所有活动都会被记录下来，因此我们可以随时审查进行了哪些操作。在基于 Debian 的 GNU/Linux 中，所有活动都记录在 <code>/var/log/auth.log</code> 文件中。</li></ol><p>本教程后面的部分阐述了这些要点。</p><h3 id="实际动手操作-sudo" tabindex="-1">实际动手操作 sudo <a class="header-anchor" href="#实际动手操作-sudo" aria-label="Permalink to “实际动手操作 sudo”">​</a></h3><p>现在，我们对 sudo 有了大致的了解。让我们实际动手操作吧。为了演示，我使用 Ubuntu。但是，其它发行版本的操作应该是相同的。</p><h4 id="允许-sudo-权限" tabindex="-1">允许 sudo 权限 <a class="header-anchor" href="#允许-sudo-权限" aria-label="Permalink to “允许 sudo 权限”">​</a></h4><p>让我们添加普通用户为 <code>sudo</code> 用户吧。在我的情形中，用户名为 <code>linuxtechi</code>。</p><ol><li>按如下所示编辑 <code>/etc/sudoers</code> 文件：</li></ol><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo visudo</span></span></code></pre></div><ol start="2"><li>添加以下行来允许用户 <code>linuxtechi</code> 有 sudo 权限：</li></ol><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>linuxtechi ALL=(ALL) ALL</span></span></code></pre></div><p>上述命令中：</p><ul><li><code>linuxtechi</code> 表示用户名</li><li>第一个 <code>ALL</code> 指示允许从任何终端、机器访问 <code>sudo</code></li><li>第二个 <code>(ALL)</code> 指示 <code>sudo</code> 命令被允许以任何用户身份执行</li><li>第三个 <code>ALL</code> 表示所有命令都可以作为 root 执行</li></ul><h4 id="以提升的权限执行命令" tabindex="-1">以提升的权限执行命令 <a class="header-anchor" href="#以提升的权限执行命令" aria-label="Permalink to “以提升的权限执行命令”">​</a></h4><p>要用提升的权限执行命令，只需要在命令前加上 <code>sudo</code>，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo cat /etc/passwd</span></span></code></pre></div><p>当你执行这个命令时，它会询问 <code>linuxtechi</code> 的密码，而不是 root 用户的密码。</p><h4 id="以其他用户执行命令" tabindex="-1">以其他用户执行命令 <a class="header-anchor" href="#以其他用户执行命令" aria-label="Permalink to “以其他用户执行命令”">​</a></h4><p>除此之外，我们可以使用 <code>sudo</code> 以另一个用户身份执行命令。例如，在下面的命令中，用户 <code>linuxtechi</code> 以用户 <code>devesh</code> 的身份执行命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo -u devesh whoami</span></span>
<span class="line"><span>[sudo] password for linuxtechi:</span></span>
<span class="line"><span>devesh</span></span></code></pre></div><h4 id="内置命令行为" tabindex="-1">内置命令行为 <a class="header-anchor" href="#内置命令行为" aria-label="Permalink to “内置命令行为”">​</a></h4><p><code>sudo</code> 的一个限制是 —— 它无法使用 Shell 的内置命令。例如， <code>history</code> 记录是内置命令，如果你试图用 <code>sudo</code> 执行这个命令，那么会提示如下的未找到命令的错误：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo history</span></span>
<span class="line"><span>[sudo] password for linuxtechi:</span></span>
<span class="line"><span>sudo: history: command not found</span></span></code></pre></div><p><strong>访问 root shell</strong></p><p>为了克服上述问题，我们可以访问 root shell，并在那里执行任何命令，包括 Shell 的内置命令。</p><p>要访问 root shell, 执行下面的命令:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo bash</span></span></code></pre></div><p>执行完这个命令后——您将观察到提示符变为井号（<code>#</code>）。</p><h3 id="技巧" tabindex="-1">技巧 <a class="header-anchor" href="#技巧" aria-label="Permalink to “技巧”">​</a></h3><p>这节我们将讨论一些有用的技巧，这将有助于提高生产力。大多数命令可用于完成日常任务。</p><h4 id="以-sudo-用户执行之前的命令" tabindex="-1">以 sudo 用户执行之前的命令 <a class="header-anchor" href="#以-sudo-用户执行之前的命令" aria-label="Permalink to “以 sudo 用户执行之前的命令”">​</a></h4><p>让我们假设你想用提升的权限执行之前的命令，那么下面的技巧将会很有用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo !4</span></span></code></pre></div><p>上面的命令将使用提升的权限执行历史记录中的第 4 条命令。</p><h4 id="在-vim-里面使用-sudo-命令" tabindex="-1">在 Vim 里面使用 sudo 命令 <a class="header-anchor" href="#在-vim-里面使用-sudo-命令" aria-label="Permalink to “在 Vim 里面使用 sudo 命令”">​</a></h4><p>很多时候，我们编辑系统的配置文件时，在保存时才意识到我们需要 root 访问权限来执行此操作。因为这个可能让我们丢失我们对文件的改动。没有必要惊慌，我们可以在 Vim 中使用下面的命令来解决这种情况：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:w !sudo tee %</span></span></code></pre></div><p>上述命令中：</p><ul><li>冒号 (<code>:</code>) 表明我们处于 Vim 的退出模式</li><li>感叹号 (<code>!</code>) 表明我们正在运行 shell 命令</li><li><code>sudo</code> 和 <code>tee</code> 都是 shell 命令</li><li>百分号 (<code>%</code>) 表明从当前行开始的所有行</li></ul><h4 id="使用-sudo-执行多个命令" tabindex="-1">使用 sudo 执行多个命令 <a class="header-anchor" href="#使用-sudo-执行多个命令" aria-label="Permalink to “使用 sudo 执行多个命令”">​</a></h4><p>至今我们用 <code>sudo</code> 只执行了单个命令，但我们可以用它执行多个命令。只需要用分号 (<code>;</code>) 隔开命令，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo -- bash -c &#39;pwd; hostname; whoami&#39;</span></span></code></pre></div><p>上述命令中</p><ul><li>双连字符 (<code>--</code>) 停止命令行切换</li><li><code>bash</code> 表示要用于执行命令的 shell 名称</li><li><code>-c</code> 选项后面跟着要执行的命令</li></ul><h4 id="无密码运行-sudo-命令" tabindex="-1">无密码运行 sudo 命令 <a class="header-anchor" href="#无密码运行-sudo-命令" aria-label="Permalink to “无密码运行 sudo 命令”">​</a></h4><p>当第一次执行 <code>sudo</code> 命令时，它会提示输入密码，默认情形下密码被缓存 15 分钟。但是，我们可以避免这个操作，并使用 <code>NOPASSWD</code> 关键字禁用密码认证，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>linuxtechi ALL=(ALL) NOPASSWD: ALL</span></span></code></pre></div><h4 id="限制用户执行某些命令" tabindex="-1">限制用户执行某些命令 <a class="header-anchor" href="#限制用户执行某些命令" aria-label="Permalink to “限制用户执行某些命令”">​</a></h4><p>为了提供受控访问，我们可以限制 <code>sudo</code> 用户只执行某些命令。例如，下面的行只允许执行 <code>echo</code> 和 <code>ls</code> 命令 。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>linuxtechi ALL=(ALL) NOPASSWD: /bin/echo /bin/ls</span></span></code></pre></div><h4 id="深入了解-sudo" tabindex="-1">深入了解 sudo <a class="header-anchor" href="#深入了解-sudo" aria-label="Permalink to “深入了解 sudo”">​</a></h4><p>让我们进一步深入了解 <code>sudo</code> 命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -l /usr/bin/sudo</span></span>
<span class="line"><span>-rwsr-xr-x 1 root root 145040 Jun 13  2017 /usr/bin/sudo</span></span></code></pre></div><p>如果仔细观察文件权限，则发现 <code>sudo</code> 上启用了 setuid 位。当任何用户运行这个二进制文件时，它将以拥有该文件的用户权限运行。在所示情形下，它是 root 用户。</p><p>为了演示这一点，我们可以使用 <code>id</code> 命令，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ id</span></span>
<span class="line"><span>uid=1002(linuxtechi) gid=1002(linuxtechi) groups=1002(linuxtechi)</span></span></code></pre></div><p>当我们不使用 <code>sudo</code> 执行 <code>id</code> 命令时，将显示用户 <code>linuxtechi</code> 的 id。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo id</span></span>
<span class="line"><span>uid=0(root) gid=0(root) groups=0(root)</span></span></code></pre></div><p>但是，如果我们使用 <code>sudo</code> 执行 <code>id</code> 命令时，则会显示 root 用户的 id。</p><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to “结论”">​</a></h3><p>从这篇文章可以看出 —— <code>sudo</code> 为普通用户提供了更多受控访问。使用这些技术，多用户可以用安全的方式与 GNU/Linux 进行交互。</p><hr>`,72)),d("p",null,[s[1]||(s[1]=i("via: ",-1)),a(e,{href:"https://www.linuxtechi.com/quick-tips-sudo-command-linux-systems/"},{default:o(()=>[...s[0]||(s[0]=[i("https://www.linuxtechi.com/quick-tips-sudo-command-linux-systems/",-1)])]),_:1})]),d("p",null,[s[5]||(s[5]=i("作者：",-1)),a(e,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:o(()=>[...s[2]||(s[2]=[i("Pradeep Kumar",-1)])]),_:1}),s[6]||(s[6]=i(" 译者：",-1)),a(e,{href:"https://github.com/szcf-weiya"},{default:o(()=>[...s[3]||(s[3]=[i("szcf-weiya",-1)])]),_:1}),s[7]||(s[7]=i(" 校对：",-1)),a(e,{href:"https://github.com/wxy"},{default:o(()=>[...s[4]||(s[4]=[i("wxy",-1)])]),_:1})]),d("p",null,[s[10]||(s[10]=i("本文由 ",-1)),a(e,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...s[8]||(s[8]=[i("LCTT",-1)])]),_:1}),s[11]||(s[11]=i(" 原创编译，",-1)),a(e,{href:"https://linux.cn/"},{default:o(()=>[...s[9]||(s[9]=[i("Linux中国",-1)])]),_:1}),s[12]||(s[12]=i(" 荣誉推出",-1))])])}const L=l(p,[["render",r]]);export{y as __pageData,L as default};
